package pe.com.dentalamericana.finance;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;@Entity@Table(name="sesiones_caja")public class CashSession{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="abierta_por",nullable=false)private Long openedBy;@Column(name="abierta_en",nullable=false,updatable=false)private Instant openedAt;@Column(name="monto_apertura",nullable=false)private BigDecimal openingAmount;@Enumerated(EnumType.STRING)@Column(nullable=false)private CashSessionStatus estado;@Column(name="cerrada_por")private Long closedBy;@Column(name="cerrada_en")private Instant closedAt;@Column(name="monto_esperado")private BigDecimal expectedAmount;@Column(name="monto_contado")private BigDecimal countedAmount;private BigDecimal diferencia;@Column(name="observacion_cierre")private String closingObservation;@Version private Long version;protected CashSession(){}public CashSession(Long actor,BigDecimal opening){openedBy=actor;openingAmount=opening;estado=CashSessionStatus.ABIERTA;}@PrePersist void create(){openedAt=Instant.now();}public void close(Long actor,BigDecimal expected,BigDecimal counted,String observation){estado=CashSessionStatus.CERRADA;closedBy=actor;closedAt=Instant.now();expectedAmount=expected;countedAmount=counted;diferencia=counted.subtract(expected);closingObservation=observation;}public Long getId(){return id;}public Long getOpenedBy(){return openedBy;}public Instant getOpenedAt(){return openedAt;}public BigDecimal getOpeningAmount(){return openingAmount;}public CashSessionStatus getStatus(){return estado;}public Long getClosedBy(){return closedBy;}public Instant getClosedAt(){return closedAt;}public BigDecimal getExpectedAmount(){return expectedAmount;}public BigDecimal getCountedAmount(){return countedAmount;}public BigDecimal getDifference(){return diferencia;}public String getClosingObservation(){return closingObservation;}public Long getVersion(){return version;}}
